   280→    persist(
   281→      (set, get) => ({
   282→        ...initialState,
   283→
   284→        // Appearance
   285→        setTheme: (theme) => set({ theme }),
   286→        setLocale: (locale) => set({ locale }),
   287→        setFontSize: (fontSize) => set({ fontSize: Math.min(Math.max(fontSize, 12), 18) }),
