   291→
   292→        // Startup
   293→        setStartupMode: (startupMode) => set({ startupMode }),
   294→        setShowStartupScreen: (showStartupScreen) => set({ showStartupScreen }),
   295→        setCheckForUpdates: (checkForUpdates) => set({ checkForUpdates }),
   296→        setAutoUpdate: (autoUpdate) => set({ autoUpdate }),
   297→
   298→        // Recording defaults
   299→        setDefaultFrameRate: (defaultFrameRate) =>
   300→          set({ defaultFrameRate: Math.min(Math.max(defaultFrameRate, 1), 60) }),
   301→        setDefaultCaptureMouseCursor: (defaultCaptureMouseCursor) =>
   302→          set({ defaultCaptureMouseCursor }),
   303→        setDefaultCaptureMouseClicks: (defaultCaptureMouseClicks) =>
   304→          set({ defaultCaptureMouseClicks }),
