   315→        setShowFrameDelays: (showFrameDelays) => set({ showFrameDelays }),
   316→        setDefaultPlaybackLoop: (defaultPlaybackLoop) => set({ defaultPlaybackLoop }),
   317→
   318→        // Export defaults
   319→        setDefaultOutputDirectory: (defaultOutputDirectory) => set({ defaultOutputDirectory }),
   320→        setRememberLastOutputDirectory: (rememberLastOutputDirectory) =>
   321→          set({ rememberLastOutputDirectory }),
   322→        setDefaultFormat: (defaultFormat) => set({ defaultFormat }),
   323→        setOpenFileAfterExport: (openFileAfterExport) => set({ openFileAfterExport }),
   324→        setCopyToClipboardAfterExport: (copyToClipboardAfterExport) =>
   325→          set({ copyToClipboardAfterExport }),
   326→
   327→        // Performance
   328→        setMaxUndoHistory: (maxUndoHistory) => set({ maxUndoHistory }),
   329→        setMaxRecentProjects: (maxRecentProjects) => set({ maxRecentProjects }),
   330→        setUseHardwareAcceleration: (useHardwareAcceleration) => set({ useHardwareAcceleration }),
   331→        setLowMemoryMode: (lowMemoryMode) => set({ lowMemoryMode }),
   332→        setCacheDirectory: (cacheDirectory) => set({ cacheDirectory }),
   333→        setMaxCacheSize: (maxCacheSize) => set({ maxCacheSize }),
   334→
   335→        // Hotkeys
   336→        setHotkey: (id, binding) =>
   337→          set((state) => ({
   338→            hotkeys: state.hotkeys.map((h) => (h.id === id ? { ...h, ...binding } : h)),
   339→          })),
   340→        resetHotkey: (id) =>
   341→          set((state) => ({
   342→            hotkeys: state.hotkeys.map((h) => {
   343→              if (h.id === id) {
   344→                const defaultHotkey = defaultHotkeys.find((dh) => dh.id === id);
   345→                return defaultHotkey ?? h;
   346→              }
   347→              return h;
   348→            }),
   349→          })),
   350→        resetAllHotkeys: () => set({ hotkeys: defaultHotkeys }),
   351→        setGlobalHotkeysEnabled: (globalHotkeysEnabled) => set({ globalHotkeysEnabled }),
   352→        getHotkeyForAction: (action) => get().hotkeys.find((h) => h.action === action),
   353→
   354→        // Advanced
   355→        setDeveloperMode: (developerMode) => set({ developerMode }),
   356→        setEnableTelemetry: (enableTelemetry) => set({ enableTelemetry }),
   357→        setLogLevel: (logLevel) => set({ logLevel }),
   358→
   359→        // Window state
   360→        setWindowSize: (windowWidth, windowHeight) => set({ windowWidth, windowHeight }),
   361→        setWindowPosition: (windowX, windowY) => set({ windowX, windowY }),
   362→        setIsMaximized: (isMaximized) => set({ isMaximized }),
   363→        setSidebarWidth: (sidebarWidth) => set({ sidebarWidth }),
   364→        setTimelineHeight: (timelineHeight) => set({ timelineHeight }),
   365→
   366→        // Bulk operations
   367→        importSettings: (settings) => set(settings),
   368→        exportSettings: () => {
   369→          const state = get();
   370→          // eslint-disable-next-line @typescript-eslint/no-unused-vars
   371→          const { importSettings, exportSettings, resetToDefaults, ...rest } = state;
   372→          return rest;
   373→        },
   374→        resetToDefaults: () => set(initialState),
   375→      }),
   376→      {
   377→        name: 'screentogif-settings',
   378→      }
   379→    )
   380→  )
   381→);
   382→
