   198→    timeline: { isOpen: true, height: 200 },
   199→    properties: { isOpen: false, width: 300 },
   200→    preview: { isOpen: true },
   201→  },
   202→  isAppLoading: true,
   203→  loadingMessage: 'Starting application...',
   204→  isBackendConnecting: false,
   205→  isBackendConnected: false,
   206→  isDragging: false,
   207→  dragSource: null,
   208→  dragData: null,
   209→  contextMenu: null,
   210→  selectionOverlay: null,
   211→  showTutorial: false,
   212→  tutorialStep: 0,
   213→  showHelpPanel: false,
   214→  focusedElement: null,
   215→};
   216→
   217→export const useUIStore = create<UIState & UIActions>()(
   218→  subscribeWithSelector((set, get) => ({
   219→    ...initialState,
   220→
   221→    // View navigation
   222→    setCurrentView: (currentView) =>
   223→      set((state) => ({ currentView, previousView: state.currentView })),
   224→    navigateBack: () =>
   225→      set((state) => ({
   226→        currentView: state.previousView ?? 'startup',
   227→        previousView: null,
   228→      })),
   229→
   230→    // Modal management
   231→    openModal: (type, data, callbacks) =>
   232→      set((state) => ({
   233→        openModals: [
   234→          ...state.openModals.filter((m) => m.type !== type),
   235→          {
   236→            type,
   237→            isOpen: true,
   238→            data,
   239→            onClose: callbacks?.onClose,
   240→            onConfirm: callbacks?.onConfirm,
   241→          },
   242→        ],
   243→      })),
   244→
   245→    closeModal: (type) =>
   246→      set((state) => {
   247→        const modal = state.openModals.find((m) => m.type === type);
   248→        modal?.onClose?.();
   249→        return { openModals: state.openModals.filter((m) => m.type !== type) };
   250→      }),
   251→
   252→    closeAllModals: () => {
   253→      const { openModals } = get();
   254→      openModals.forEach((m) => m.onClose?.());
   255→      set({ openModals: [] });
   256→    },
   257→
   258→    isModalOpen: (type) => get().openModals.some((m) => m.type === type && m.isOpen),
   259→
   260→    getModalData: <T,>(type: ModalType) => {
   261→      const modal = get().openModals.find((m) => m.type === type);
   262→      return modal?.data as T | undefined;
   263→    },
   264→
   265→    // Toast management
   266→    showToast: (toast) => {
   267→      const id = crypto.randomUUID();
   268→      set((state) => {
   269→        const newToast: Toast = {
   270→          ...toast,
   271→          id,
   272→          createdAt: Date.now(),
   273→          duration: toast.duration ?? 5000,
   274→          dismissible: toast.dismissible ?? true,
   275→        };
   276→        const toasts = [newToast, ...state.toasts].slice(0, state.maxToasts);
   277→        return { toasts };
   278→      });
   279→
   280→      // Auto-dismiss if duration > 0
   281→      if (toast.duration !== 0) {
   282→        setTimeout(() => {
   283→          get().dismissToast(id);
   284→        }, toast.duration ?? 5000);
   285→      }
   286→
   287→      return id;
   288→    },
   289→
   290→    dismissToast: (id) =>
   291→      set((state) => ({ toasts: state.toasts.filter((t) => t.id !== id) })),
   292→
   293→    dismissAllToasts: () => set({ toasts: [] }),
   294→
   295→    showSuccessToast: (title, message) =>
   296→      get().showToast({ type: 'success', title, message, dismissible: true }),
   297→
   298→    showErrorToast: (title, message) =>
   299→      get().showToast({ type: 'error', title, message, duration: 0, dismissible: true }),
   300→
   301→    showInfoToast: (title, message) =>
   302→      get().showToast({ type: 'info', title, message, dismissible: true }),
   303→
   304→    showWarningToast: (title, message) =>
   305→      get().showToast({ type: 'warning', title, message, dismissible: true }),
   306→
   307→    // Panel management
   308→    togglePanel: (panelId) =>
   309→      set((state) => ({
   310→        panelStates: {
   311→          ...state.panelStates,
   312→          [panelId]: {
   313→            ...state.panelStates[panelId],
   314→            isOpen: !state.panelStates[panelId].isOpen,
   315→          },
   316→        },
   317→      })),
   318→
   319→    setPanelOpen: (panelId, isOpen) =>
   320→      set((state) => ({
   321→        panelStates: {
   322→          ...state.panelStates,
   323→          [panelId]: { ...state.panelStates[panelId], isOpen },
   324→        },
   325→      })),
   326→
   327→    setPanelSize: (panelId, size) =>
   328→      set((state) => ({
   329→        panelStates: {
   330→          ...state.panelStates,
   331→          [panelId]: { ...state.panelStates[panelId], ...size },
   332→        },
   333→      })),
   334→
   335→    // Loading states
   336→    setAppLoading: (isAppLoading, loadingMessage) =>
   337→      set({ isAppLoading, loadingMessage: loadingMessage ?? null }),
   338→
   339→    setBackendConnecting: (isBackendConnecting) => set({ isBackendConnecting }),
   340→
   341→    setBackendConnected: (isBackendConnected) => set({ isBackendConnected }),
   342→
   343→    // Drag and drop
   344→    startDrag: (dragSource, dragData) => set({ isDragging: true, dragSource, dragData }),
   345→    endDrag: () => set({ isDragging: false, dragSource: null, dragData: null }),
   346→
   347→    // Context menu
   348→    showContextMenu: (x, y, items) =>
   349→      set({ contextMenu: { isOpen: true, x, y, items } }),
   350→    hideContextMenu: () => set({ contextMenu: null }),
   351→
   352→    // Selection overlay
   353→    startSelection: (x, y) =>
   354→      set({ selectionOverlay: { isActive: true, startX: x, startY: y, endX: x, endY: y } }),
   355→
   356→    updateSelection: (x, y) =>
   357→      set((state) => ({
   358→        selectionOverlay: state.selectionOverlay
   359→          ? { ...state.selectionOverlay, endX: x, endY: y }
   360→          : null,
   361→      })),
   362→
   363→    endSelection: () => {
   364→      const { selectionOverlay } = get();
   365→      if (!selectionOverlay) return null;
   366→
   367→      const x = Math.min(selectionOverlay.startX, selectionOverlay.endX);
   368→      const y = Math.min(selectionOverlay.startY, selectionOverlay.endY);
   369→      const width = Math.abs(selectionOverlay.endX - selectionOverlay.startX);
   370→      const height = Math.abs(selectionOverlay.endY - selectionOverlay.startY);
   371→
   372→      set({ selectionOverlay: null });
   373→      return { x, y, width, height };
   374→    },
   375→
   376→    cancelSelection: () => set({ selectionOverlay: null }),
   377→
   378→    // Help/Tutorial
   379→    setShowTutorial: (showTutorial) => set({ showTutorial }),
   380→    nextTutorialStep: () => set((state) => ({ tutorialStep: state.tutorialStep + 1 })),
   381→    prevTutorialStep: () =>
   382→      set((state) => ({ tutorialStep: Math.max(0, state.tutorialStep - 1) })),
   383→    setTutorialStep: (tutorialStep) => set({ tutorialStep }),
   384→    setShowHelpPanel: (showHelpPanel) => set({ showHelpPanel }),
   385→
   386→    // Focus
   387→    setFocusedElement: (focusedElement) => set({ focusedElement }),
   388→
   389→    // Reset
   390→    reset: () => set(initialState),
   391→  }))
   392→);
   393→
   394→// Selector hooks
   395→export const selectCurrentView = (state: UIState) => state.currentView;
   396→export const selectIsLoading = (state: UIState) => state.isAppLoading;
   397→export const selectToasts = (state: UIState) => state.toasts;
   398→export const selectIsBackendConnected = (state: UIState) => state.isBackendConnected;
   399→

