    36→  private translations: Map<AppLocale, TranslationDictionary> = new Map();
    37→  private fallbackLocale: AppLocale = 'en';
    38→  private _isInitialized = false;
    39→  private loadingPromises: Map<AppLocale, Promise<void>> = new Map();
    40→  private pluralRules: Map<AppLocale, PluralRule> = new Map();
    41→
    42→  constructor() {
    43→    this.initPluralRules();
    44→  }
    45→
    46→  /**
    47→   * Initialize the service with a locale
    48→   */
    49→  async initialize(locale: AppLocale = 'en'): Promise<void> {
    50→    await this.loadTranslations(locale);
    51→
    52→    // Also load fallback locale
    53→    if (locale !== this.fallbackLocale) {
    54→      await this.loadTranslations(this.fallbackLocale);
    55→    }
    56→
    57→    this.currentLocale = locale;
    58→    this._isInitialized = true;
    59→  }
    60→
    61→  /**
    62→   * Check if service is initialized
    63→   */
    64→  isInitialized(): boolean {
    65→    return this._isInitialized;
    66→  }
    67→
    68→  /**
    69→   * Get current locale
    70→   */
    71→  getLocale(): AppLocale {
    72→    return this.currentLocale;
    73→  }
    74→
    75→  /**
    76→   * Set current locale
    77→   */
    78→  async setLocale(locale: AppLocale): Promise<void> {
    79→    if (!SUPPORTED_LOCALES[locale]) {
    80→      console.warn(`Unsupported locale: ${locale}`);
    81→      return;
    82→    }
    83→
    84→    await this.loadTranslations(locale);
    85→    this.currentLocale = locale;
    86→
    87→    // Update document lang attribute
    88→    document.documentElement.lang = locale;
    89→  }
    90→
    91→  /**
    92→   * Load translations for a locale
    93→   */
    94→  async loadTranslations(locale: AppLocale): Promise<void> {
    95→    // Check if already loaded
    96→    if (this.translations.has(locale)) {
    97→      return;
    98→    }
    99→
   100→    // Check if loading is in progress
   101→    const existingPromise = this.loadingPromises.get(locale);
   102→    if (existingPromise) {
   103→      return existingPromise;
   104→    }
   105→
   106→    // Load translations
   107→    const loadPromise = this.fetchTranslations(locale);
   108→    this.loadingPromises.set(locale, loadPromise);
   109→
   110→    try {
   111→      await loadPromise;
   112→    } finally {
   113→      this.loadingPromises.delete(locale);
   114→    }
   115→  }
   116→
   117→  /**
   118→   * Translate a key
   119→   */
   120→  t(key: string, options?: InterpolationOptions): string {
   121→    const translation = this.getTranslation(key);
   122→
   123→    if (!translation) {
   124→      console.warn(`Missing translation for key: ${key}`);
   125→      return key;
   126→    }
   127→
   128→    if (options) {
   129→      return this.interpolate(translation, options);
   130→    }
   131→
   132→    return translation;
   133→  }
   134→
   135→  /**
   136→   * Translate with pluralization
   137→   */
   138→  tp(key: string, count: number, options?: InterpolationOptions): string {
   139→    const pluralForm = this.getPluralForm(count);
   140→    const pluralKey = `${key}.${pluralForm}`;
   141→
   142→    // Try plural form first, then fall back to base key
   143→    let translation = this.getTranslation(pluralKey);
   144→    if (!translation) {
   145→      translation = this.getTranslation(`${key}.other`);
   146→    }
   147→    if (!translation) {
   148→      translation = this.getTranslation(key);
   149→    }
   150→
   151→    if (!translation) {
   152→      console.warn(`Missing translation for key: ${key}`);
   153→      return key;
   154→    }
   155→
   156→    const interpolationOptions = { ...options, count };
   157→    return this.interpolate(translation, interpolationOptions);
   158→  }
   159→
   160→  /**
   161→   * Check if a translation exists
   162→   */
   163→  hasTranslation(key: string): boolean {
   164→    return this.getTranslation(key) !== null;
   165→  }
   166→
   167→  /**
   168→   * Get all supported locales
   169→   */
   170→  getSupportedLocales(): { code: AppLocale; name: string }[] {
   171→    return Object.entries(SUPPORTED_LOCALES).map(([code, name]) => ({
   172→      code: code as AppLocale,
   173→      name,
   174→    }));
   175→  }
   176→
   177→  /**
   178→   * Get the display name for a locale
   179→   */
   180→  getLocaleName(locale: AppLocale): string {
   181→    return SUPPORTED_LOCALES[locale] ?? locale;
   182→  }
   183→
   184→  /**
   185→   * Format a number according to current locale
   186→   */
   187→  formatNumber(value: number, options?: Intl.NumberFormatOptions): string {
   188→    return new Intl.NumberFormat(this.currentLocale, options).format(value);
   189→  }
   190→
   191→  /**
   192→   * Format a date according to current locale
   193→   */
   194→  formatDate(date: Date | number | string, options?: Intl.DateTimeFormatOptions): string {
   195→    const dateObj = typeof date === 'string' ? new Date(date) : date;
   196→    return new Intl.DateTimeFormat(this.currentLocale, options).format(dateObj);
   197→  }
   198→
   199→  /**
   200→   * Format a relative time
   201→   */
   202→  formatRelativeTime(value: number, unit: Intl.RelativeTimeFormatUnit): string {
   203→    const rtf = new Intl.RelativeTimeFormat(this.currentLocale, { numeric: 'auto' });
   204→    return rtf.format(value, unit);
   205→  }
   206→
   207→  /**
   208→   * Format duration in human readable format
   209→   */
   210→  formatDuration(milliseconds: number): string {
   211→    const seconds = Math.floor(milliseconds / 1000);
   212→    const minutes = Math.floor(seconds / 60);
   213→    const hours = Math.floor(minutes / 60);
   214→
   215→    if (hours > 0) {
   216→      return this.t('time.hoursMinutes', {
   217→        hours: hours.toString(),
   218→        minutes: (minutes % 60).toString(),
   219→      });
   220→    }
   221→
   222→    if (minutes > 0) {
   223→      return this.t('time.minutesSeconds', {
   224→        minutes: minutes.toString(),
   225→        seconds: (seconds % 60).toString(),
   226→      });
   227→    }
   228→
   229→    return this.tp('time.seconds', seconds, { count: seconds.toString() });
   230→  }
   231→
   232→  /**
   233→   * Format file size
   234→   */
   235→  formatFileSize(bytes: number): string {
   236→    const units = ['B', 'KB', 'MB', 'GB', 'TB'];
   237→    let size = bytes;
   238→    let unitIndex = 0;
   239→
   240→    while (size >= 1024 && unitIndex < units.length - 1) {
   241→      size /= 1024;
   242→      unitIndex++;
   243→    }
   244→
   245→    return `${this.formatNumber(size, { maximumFractionDigits: 2 })} ${units[unitIndex]}`;
   246→  }
   247→
   248→  private async fetchTranslations(locale: AppLocale): Promise<void> {
   249→    try {
   250→      // In a real implementation, this would fetch from a JSON file or API
   251→      // For now, we'll use a placeholder that would be replaced with actual translation loading
   252→      const response = await fetch(`/locales/${locale}.json`);
   253→      if (!response.ok) {
   254→        throw new Error(`Failed to load translations for ${locale}`);
   255→      }
   256→      const translations = await response.json();
   257→      this.translations.set(locale, translations);
   258→    } catch (error) {
   259→      console.error(`Failed to load translations for ${locale}:`, error);
   260→      // Set empty translations to prevent repeated loading attempts
   261→      this.translations.set(locale, {});
   262→    }
   263→  }
   264→
   265→  private getTranslation(key: string): string | null {
   266→    // Try current locale first
   267→    let translation = this.getNestedValue(this.translations.get(this.currentLocale), key);
   268→
   269→    // Fall back to fallback locale
   270→    if (!translation && this.currentLocale !== this.fallbackLocale) {
   271→      translation = this.getNestedValue(this.translations.get(this.fallbackLocale), key);
   272→    }
   273→
   274→    return translation;
   275→  }
   276→
   277→  private getNestedValue(obj: TranslationDictionary | undefined, key: string): string | null {
   278→    if (!obj) return null;
   279→
   280→    const keys = key.split('.');
   281→    let current: TranslationDictionary | string = obj;
   282→
   283→    for (const k of keys) {
   284→      if (typeof current !== 'object' || current === null) {
   285→        return null;
   286→      }
   287→      current = current[k] as TranslationDictionary | string;
   288→      if (current === undefined) {
   289→        return null;
   290→      }
   291→    }
   292→
   293→    return typeof current === 'string' ? current : null;
   294→  }
   295→
   296→  private interpolate(template: string, options: InterpolationOptions): string {
   297→    return template.replace(/\{\{(\w+)\}\}/g, (match, key) => {
   298→      const value = options[key];
   299→      return value !== undefined ? String(value) : match;
   300→    });
   301→  }
   302→
   303→  private getPluralForm(count: number): string {
   304→    const rule = this.pluralRules.get(this.currentLocale);
   305→    if (rule) {
   306→      return rule(count);
   307→    }
   308→    // Default English-like rules
   309→    return count === 1 ? 'one' : 'other';
   310→  }
   311→
   312→  private initPluralRules(): void {
   313→    // English-like (en, de, es, fr, pt)
   314→    const englishLike: PluralRule = (n) => (n === 1 ? 'one' : 'other');
   315→    this.pluralRules.set('en', englishLike);
   316→    this.pluralRules.set('de', englishLike);
   317→    this.pluralRules.set('es', englishLike);
   318→    this.pluralRules.set('fr', englishLike);
   319→    this.pluralRules.set('pt', englishLike);
   320→
   321→    // Russian
   322→    const russian: PluralRule = (n) => {
   323→      const mod10 = n % 10;
   324→      const mod100 = n % 100;
   325→      if (mod10 === 1 && mod100 !== 11) return 'one';
   326→      if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return 'few';
   327→      return 'many';
   328→    };
   329→    this.pluralRules.set('ru', russian);
   330→
   331→    // East Asian (zh, ja, ko) - no plural forms
   332→    const eastAsian: PluralRule = () => 'other';
   333→    this.pluralRules.set('zh', eastAsian);
   334→    this.pluralRules.set('ja', eastAsian);
   335→    this.pluralRules.set('ko', eastAsian);
   336→  }
   337→}
   338→
   339→// Singleton instance
   340→export const LocalizationService = new LocalizationServiceImpl();
   341→
   342→// Convenience function for translations
   343→export function t(key: string, options?: InterpolationOptions): string {
   344→  return LocalizationService.t(key, options);
   345→}
   346→
   347→// Convenience function for plural translations
   348→export function tp(key: string, count: number, options?: InterpolationOptions): string {
   349→  return LocalizationService.tp(key, count, options);
   350→}
   351→

