     1→import { useState, useRef, type ReactNode, type KeyboardEvent } from 'react';
     2→
     3→export type TabsVariant = 'line' | 'pills' | 'enclosed';
     4→export type TabsSize = 'sm' | 'md' | 'lg';
     5→
     6→export interface Tab {
     7→  id: string;
     8→  label: string;
     9→  icon?: ReactNode;
    10→  disabled?: boolean;
    11→  content?: ReactNode;
    12→}
    13→
    14→export interface TabsProps {
    15→  tabs: Tab[];
    16→  activeTab?: string;
    17→  onChange?: (tabId: string) => void;
    18→  variant?: TabsVariant;
    19→  size?: TabsSize;
    20→  fullWidth?: boolean;
    21→  className?: string;
    22→  children?: ReactNode;
    23→}
    24→
    25→const sizeStyles: Record<TabsSize, string> = {
    26→  sm: 'text-xs px-3 py-1.5',
    27→  md: 'text-sm px-4 py-2',
    28→  lg: 'text-base px-5 py-2.5',
    29→};
    30→
    31→const variantStyles: Record<TabsVariant, { container: string; tab: string; active: string }> = {
    32→  line: {
    33→    container: 'border-b border-surface-700',
    34→    tab: 'border-b-2 border-transparent -mb-px hover:text-surface-100 hover:border-surface-500',
    35→    active: 'border-primary-500 text-surface-100',
    36→  },
    37→  pills: {
    38→    container: 'gap-1',
    39→    tab: 'rounded-lg hover:bg-surface-700',
    40→    active: 'bg-primary-600 text-white hover:bg-primary-600',
    41→  },
    42→  enclosed: {
    43→    container: 'border-b border-surface-700',
    44→    tab: 'border border-transparent rounded-t-lg -mb-px hover:bg-surface-800',
    45→    active: 'border-surface-700 border-b-surface-900 bg-surface-900 text-surface-100',
    46→  },
    47→};
    48→
    49→export function Tabs({
    50→  tabs,
    51→  activeTab,
    52→  onChange,
    53→  variant = 'line',
    54→  size = 'md',
    55→  fullWidth = false,
    56→  className = '',
    57→  children,
    58→}: TabsProps) {
    59→  const [, setFocusedIndex] = useState(-1);
    60→  const tabRefs = useRef<(HTMLButtonElement | null)[]>([]);
    61→
    62→  const handleTabClick = (tab: Tab) => {
    63→    if (tab.disabled) return;
    64→    onChange?.(tab.id);
    65→  };
    66→
    67→  const handleKeyDown = (e: KeyboardEvent, index: number) => {
    68→    const enabledTabs = tabs
    69→      .map((tab, i) => ({ tab, index: i }))
    70→      .filter(({ tab }) => !tab.disabled);
    71→
    72→    const currentEnabledIndex = enabledTabs.findIndex(({ index: i }) => i === index);
    73→
    74→    let newIndex: number | undefined;
    75→
    76→    switch (e.key) {
    77→      case 'ArrowLeft':
    78→        e.preventDefault();
    79→        if (currentEnabledIndex > 0) {
    80→          newIndex = enabledTabs[currentEnabledIndex - 1].index;
    81→        } else {
    82→          newIndex = enabledTabs[enabledTabs.length - 1].index;
    83→        }
    84→        break;
    85→      case 'ArrowRight':
    86→        e.preventDefault();
    87→        if (currentEnabledIndex < enabledTabs.length - 1) {
    88→          newIndex = enabledTabs[currentEnabledIndex + 1].index;
    89→        } else {
    90→          newIndex = enabledTabs[0].index;
    91→        }
    92→        break;
    93→      case 'Home':
    94→        e.preventDefault();
    95→        newIndex = enabledTabs[0].index;
    96→        break;
    97→      case 'End':
    98→        e.preventDefault();
    99→        newIndex = enabledTabs[enabledTabs.length - 1].index;
   100→        break;
   101→      case 'Enter':
   102→      case ' ':
   103→        e.preventDefault();
   104→        handleTabClick(tabs[index]);
   105→        return;
   106→    }
   107→
   108→    if (newIndex !== undefined) {
   109→      setFocusedIndex(newIndex);
   110→      tabRefs.current[newIndex]?.focus();
   111→    }
   112→  };
   113→
   114→  const activeContent = tabs.find((t) => t.id === activeTab)?.content;
   115→
   116→  return (
   117→    <div className={className}>
   118→      {/* Tab list */}
   119→      <div
   120→        role="tablist"
   121→        className={`
   122→          flex
   123→          ${variantStyles[variant].container}
   124→          ${fullWidth ? 'w-full' : 'w-fit'}
   125→        `}
   126→      >
   127→        {tabs.map((tab, index) => (
   128→          <button
   129→            key={tab.id}
   130→            ref={(el) => { tabRefs.current[index] = el; }}
   131→            role="tab"
   132→            aria-selected={tab.id === activeTab}
   133→            aria-controls={`tabpanel-${tab.id}`}
   134→            tabIndex={tab.id === activeTab ? 0 : -1}
   135→            disabled={tab.disabled}
   136→            onClick={() => handleTabClick(tab)}
   137→            onKeyDown={(e) => handleKeyDown(e, index)}
   138→            className={`
