/**
 * HotkeyConflictWarning Component
 * Warning display for conflicting hotkey bindings
 */

import { Icon } from '../../../../components/atoms/Icon';
import type { HotkeyBinding } from '../../../../stores/settingsStore';
import { HotkeyService } from '../../../../services/HotkeyService';

export interface HotkeyConflictWarningProps {
  conflictingBindings: HotkeyBinding[];
  className?: string;
}

export function HotkeyConflictWarning({
  conflictingBindings,
  className = '',
}: HotkeyConflictWarningProps) {
  if (conflictingBindings.length < 2) {
    return null;
  }

  const hotkeyDisplay = HotkeyService.getHotkeyDisplayString(conflictingBindings[0]);

  return (
    <div
      className={`
        flex items-start gap-3 p-4
        bg-accent-warning/10 border border-accent-warning/30
        rounded-lg
        ${className}
      `}
    >
      <Icon name="exclamation-triangle" size="md" className="text-accent-warning flex-shrink-0" />
      <div>
        <h4 className="text-sm font-medium text-accent-warning mb-1">Hotkey Conflict</h4>
        <p className="text-xs text-surface-300 mb-2">
          The key combination <kbd className="px-1 py-0.5 bg-surface-700 rounded">{hotkeyDisplay}</kbd> is assigned to multiple actions:
        </p>
        <ul className="text-xs text-surface-400 space-y-1">
          {conflictingBindings.map((binding) => (
            <li key={binding.id} className="flex items-center gap-2">
              <span className="w-2 h-2 bg-accent-warning rounded-full" />
              <span>{binding.action.replace(/\./g, ' > ')}</span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

HotkeyConflictWarning.displayName = 'HotkeyConflictWarning';

/**
 * HotkeyEditor Component
 * Individual hotkey binding editor with key capture functionality
 */

import { useState, useRef, useCallback, useEffect } from 'react';
import { Icon } from '../../../../components/atoms/Icon';
import { Button } from '../../../../components/atoms/Button';
import type { HotkeyBinding } from '../../../../stores/settingsStore';
import { HotkeyService } from '../../../../services/HotkeyService';

export interface HotkeyEditorProps {
  binding: HotkeyBinding;
  onChange: (id: string, updates: Partial<HotkeyBinding>) => void;
  onReset: (id: string) => void;
  disabled?: boolean;
  hasConflict?: boolean;
  className?: string;
}

export function HotkeyEditor({
  binding,
  onChange,
  onReset,
  disabled = false,
  hasConflict = false,
  className = '',
}: HotkeyEditorProps) {
  const [isCapturing, setIsCapturing] = useState(false);
  const inputRef = useRef<HTMLButtonElement>(null);

  const displayString = HotkeyService.getHotkeyDisplayString(binding);
  const actionLabel = binding.action.split('.').map((part) =>
    part.charAt(0).toUpperCase() + part.slice(1)
  ).join(' > ');

  const handleKeyCapture = useCallback(
    (event: KeyboardEvent) => {
      event.preventDefault();
      event.stopPropagation();

      // Ignore modifier keys alone
      if (['Control', 'Alt', 'Shift', 'Meta'].includes(event.key)) {
        return;
      }

      // Escape cancels capture
      if (event.key === 'Escape') {
        setIsCapturing(false);
        return;
      }

      const newBinding: Partial<HotkeyBinding> = {
        key: event.key,
        modifiers: {
          ctrl: event.ctrlKey,
          alt: event.altKey,
          shift: event.shiftKey,
          meta: event.metaKey,
        },
      };

      onChange(binding.id, newBinding);
      setIsCapturing(false);
    },
    [binding.id, onChange]
  );

  useEffect(() => {
    if (isCapturing) {
      // Temporarily disable hotkey service during capture
      HotkeyService.setEnabled(false);
      window.addEventListener('keydown', handleKeyCapture);

      return () => {
        window.removeEventListener('keydown', handleKeyCapture);
        HotkeyService.setEnabled(true);
      };
    }
  }, [isCapturing, handleKeyCapture]);

  const handleStartCapture = () => {
    if (!disabled) {
      setIsCapturing(true);
    }
  };

  const handleCancelCapture = () => {
    setIsCapturing(false);
  };

  const handleToggleEnabled = () => {
    onChange(binding.id, { enabled: !binding.enabled });
  };

  return (
    <div
      className={`
        flex items-center gap-3 p-3
        bg-surface-800 border rounded-lg
        ${hasConflict ? 'border-accent-warning/50' : 'border-surface-700'}
        ${!binding.enabled ? 'opacity-60' : ''}
        ${className}
      `}
    >
      {/* Enable toggle */}
      <button
        type="button"
        onClick={handleToggleEnabled}
        disabled={disabled}
        className="text-surface-400 hover:text-surface-200 disabled:cursor-not-allowed"
        title={binding.enabled ? 'Disable' : 'Enable'}
      >
        <Icon name={binding.enabled ? 'check-circle' : 'circle'} size="sm" />
      </button>

      {/* Action label */}
      <div className="flex-1 min-w-0">
        <span className="text-sm text-surface-200 truncate block">{actionLabel}</span>
      </div>

      {/* Key binding */}
      <button
        ref={inputRef}
        type="button"
        onClick={handleStartCapture}
        disabled={disabled || !binding.enabled}
        className={`
          min-w-[120px] px-3 py-1.5
          bg-surface-700 border rounded-lg
          text-sm font-mono text-center
          transition-colors
          ${
            isCapturing
              ? 'border-primary-500 ring-2 ring-primary-500/50 text-primary-400'
              : hasConflict
                ? 'border-accent-warning/50 text-accent-warning'
                : 'border-surface-600 text-surface-200 hover:border-surface-500'
          }
          disabled:opacity-50 disabled:cursor-not-allowed
        `}
      >
        {isCapturing ? 'Press keys...' : displayString}
      </button>

      {/* Reset button */}
      <button
        type="button"
        onClick={() => onReset(binding.id)}
        disabled={disabled}
