  } = useSettingsStore();

  // Find conflicting hotkeys
  const conflicts = useMemo(() => {
    const hotkeyMap = new Map<string, HotkeyBinding[]>();

    hotkeys.filter(h => h.enabled).forEach((binding) => {
      const key = HotkeyService.getHotkeyDisplayString(binding);
