 * Displays application version and update information
 */

import { useState, useEffect } from 'react';
import { Button } from '../../../../components/atoms/Button';
import { Icon } from '../../../../components/atoms/Icon';

export interface VersionInfoProps {
  className?: string;
}

interface AppVersion {
  version: string;
  buildNumber: string;
  buildDate: string;
  platform: string;
  arch: string;
}

export function VersionInfo({ className = '' }: VersionInfoProps) {
  const [versionInfo, setVersionInfo] = useState<AppVersion | null>(null);
  const [isCheckingUpdate, setIsCheckingUpdate] = useState(false);
  const [updateStatus, setUpdateStatus] = useState<'none' | 'available' | 'uptodate'>('none');

  useEffect(() => {
    // Simulate loading version info
    // In real implementation, this would come from Tauri or package.json
    setVersionInfo({
      version: '3.0.0',
      buildNumber: '2024.12.17.1',
      buildDate: new Date().toISOString(),
      platform: navigator.platform || 'Unknown',
      arch: 'x64',
    });
  }, []);

  const handleCheckForUpdates = async () => {
    setIsCheckingUpdate(true);
    setUpdateStatus('none');

    // Simulate update check
    await new Promise((resolve) => setTimeout(resolve, 2000));

    // Randomly show update available or up to date
    setUpdateStatus(Math.random() > 0.7 ? 'available' : 'uptodate');
    setIsCheckingUpdate(false);
  };

  if (!versionInfo) {
    return (
      <div className={`animate-pulse ${className}`}>
        <div className="h-4 bg-surface-700 rounded w-1/3 mb-2" />
        <div className="h-3 bg-surface-700 rounded w-1/2" />
      </div>
    );
  }

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Version Display */}
      <div className="flex items-center gap-4">
        <div className="w-16 h-16 bg-gradient-to-br from-primary-500 to-primary-700 rounded-xl flex items-center justify-center">
          <Icon name="record" size="xl" className="text-white" />
        </div>
        <div>
          <h4 className="text-xl font-bold text-surface-100">ScreenToGif</h4>
          <p className="text-sm text-surface-400">
            Version {versionInfo.version} ({versionInfo.buildNumber})
          </p>
        </div>
      </div>

      {/* Version Details */}
      <div className="grid grid-cols-2 gap-4 p-4 bg-surface-800 rounded-lg border border-surface-700">
        <div>
          <span className="text-xs text-surface-500">Platform</span>
          <p className="text-sm text-surface-200">{versionInfo.platform}</p>
        </div>
        <div>
          <span className="text-xs text-surface-500">Architecture</span>
          <p className="text-sm text-surface-200">{versionInfo.arch}</p>
        </div>
        <div>
          <span className="text-xs text-surface-500">Build Date</span>
          <p className="text-sm text-surface-200">
            {new Date(versionInfo.buildDate).toLocaleDateString()}
          </p>
        </div>
        <div>
          <span className="text-xs text-surface-500">Framework</span>
          <p className="text-sm text-surface-200">Tauri 2.0 + React</p>
        </div>
      </div>

      {/* Update Status */}
      {updateStatus === 'available' && (
        <div className="flex items-center gap-3 p-4 bg-accent-success/10 border border-accent-success/30 rounded-lg">
          <Icon name="arrow-down" size="md" className="text-accent-success" />
          <div className="flex-1">
            <h5 className="text-sm font-medium text-accent-success">Update Available</h5>
            <p className="text-xs text-surface-400">Version 3.1.0 is ready to download</p>
          </div>
          <Button variant="primary" size="sm">
            Download
          </Button>
        </div>
      )}

      {updateStatus === 'uptodate' && (
        <div className="flex items-center gap-3 p-4 bg-surface-800 border border-surface-700 rounded-lg">
          <Icon name="check-circle" size="md" className="text-accent-success" />
          <div>
            <h5 className="text-sm font-medium text-surface-200">Up to Date</h5>
            <p className="text-xs text-surface-400">You have the latest version</p>
          </div>
        </div>
      )}

      {/* Check for Updates Button */}
      <Button
        variant="secondary"
        onClick={handleCheckForUpdates}
        disabled={isCheckingUpdate}
        className="w-full"
      >
        {isCheckingUpdate ? (
          <>
            <Icon name="spinner" size="sm" className="mr-2 animate-spin" />
            Checking for updates...
          </>
        ) : (
          <>
            <Icon name="arrow-path" size="sm" className="mr-2" />
            Check for Updates
          </>
        )}
      </Button>
    </div>
  );
}

VersionInfo.displayName = 'VersionInfo';

/**
 * AboutSection Component
 * Container for about page information
 */

import { useSettingsStore } from '../../../../stores/settingsStore';
import { Toggle } from '../../../../components/atoms/Toggle';
import { Button } from '../../../../components/atoms/Button';
import { Icon } from '../../../../components/atoms/Icon';
import { VersionInfo } from './VersionInfo';
import { LicenseInfo } from './LicenseInfo';

export interface AboutSectionProps {
  className?: string;
}

export function AboutSection({ className = '' }: AboutSectionProps) {
  const {
    developerMode,
    enableTelemetry,
    logLevel,
    setDeveloperMode,
    setEnableTelemetry,
    setLogLevel,
    exportSettings,
    importSettings,
    resetToDefaults,
  } = useSettingsStore();

  const handleExportSettings = () => {
    const settings = exportSettings();
    const blob = new Blob([JSON.stringify(settings, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'screentogif-settings.json';
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImportSettings = async () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = async (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file) {
        try {
          const text = await file.text();
          const settings = JSON.parse(text);
          importSettings(settings);
        } catch (error) {
          console.error('Failed to import settings:', error);
        }
      }
    };
    input.click();
  };

  const handleResetSettings = () => {
    if (confirm('Are you sure you want to reset all settings to defaults? This cannot be undone.')) {
      resetToDefaults();
    }
  };

  return (
    <div className={`space-y-8 ${className}`}>
      {/* Version Info */}
      <section>
        <h3 className="text-lg font-semibold text-surface-100 mb-4">About</h3>
        <VersionInfo />
      </section>

      {/* License Info */}
      <section>
        <h3 className="text-lg font-semibold text-surface-100 mb-4">License & Credits</h3>
        <LicenseInfo />
      </section>

      {/* Advanced Settings */}
      <section>
        <h3 className="text-lg font-semibold text-surface-100 mb-4">Advanced</h3>
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <label className="block text-sm font-medium text-surface-200">Developer mode</label>
              <p className="text-xs text-surface-500">Enable advanced debugging features</p>
            </div>
            <Toggle
              checked={developerMode}
              onChange={(e) => setDeveloperMode(e.target.checked)}
              size="sm"
            />
          </div>

          <div className="flex items-center justify-between">
            <div>
              <label className="block text-sm font-medium text-surface-200">
                Usage analytics
              </label>
              <p className="text-xs text-surface-500">
                Help improve ScreenToGif with anonymous data
              </p>
            </div>
            <Toggle
              checked={enableTelemetry}
              onChange={(e) => setEnableTelemetry(e.target.checked)}
              size="sm"
            />
          </div>

          {developerMode && (
            <div className="ml-4 pl-4 border-l border-surface-700 space-y-2">
              <label className="block text-sm font-medium text-surface-200">Log level</label>
              <div className="flex gap-2">
                {(['debug', 'info', 'warn', 'error'] as const).map((level) => (
                  <button
                    key={level}
                    type="button"
                    onClick={() => setLogLevel(level)}
                    className={`
                      px-3 py-1.5 rounded-lg text-sm capitalize transition-colors
                      ${
                        logLevel === level
                          ? 'bg-primary-500 text-white'
                          : 'bg-surface-700 text-surface-300 hover:bg-surface-600'
                      }
                    `}
                  >
                    {level}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </section>

      {/* Settings Management */}
      <section>
        <h3 className="text-lg font-semibold text-surface-100 mb-4">Settings Management</h3>
        <div className="grid grid-cols-3 gap-3">
          <Button variant="secondary" onClick={handleExportSettings} className="w-full">
            <Icon name="arrow-up" size="sm" className="mr-2" />
            Export
          </Button>
          <Button variant="secondary" onClick={handleImportSettings} className="w-full">
            <Icon name="arrow-down" size="sm" className="mr-2" />
            Import
          </Button>
          <Button variant="secondary" onClick={handleResetSettings} className="w-full text-accent-error hover:bg-accent-error/10">
            <Icon name="arrow-path" size="sm" className="mr-2" />
            Reset All
          </Button>
        </div>
        <p className="text-xs text-surface-500 mt-2">
          Export your settings to back them up, or import settings from another device.
        </p>
      </section>

      {/* Support Links */}
      <section className="pt-4 border-t border-surface-700">
        <div className="flex flex-wrap gap-3">
          <a
            href="https://github.com/NickeManarin/ScreenToGif/issues"
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center gap-2 text-sm text-primary-400 hover:text-primary-300 transition-colors"
          >
            <Icon name="exclamation-circle" size="sm" />
            Report a Bug
          </a>
          <a
            href="https://github.com/NickeManarin/ScreenToGif/discussions"
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center gap-2 text-sm text-primary-400 hover:text-primary-300 transition-colors"
          >
            <Icon name="chat-bubble-left" size="sm" />
            Discussions
          </a>
          <a
            href="https://www.screentogif.com"
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center gap-2 text-sm text-primary-400 hover:text-primary-300 transition-colors"
          >
            <Icon name="globe" size="sm" />
            Website
          </a>
        </div>
      </section>
    </div>
  );
}

AboutSection.displayName = 'AboutSection';

export { AboutSection, type AboutSectionProps } from './AboutSection';
export { VersionInfo, type VersionInfoProps } from './VersionInfo';
export { LicenseInfo, type LicenseInfoProps } from './LicenseInfo';

